ações no navegador<small><?= !$pushNotificationsAvailable?'Configuração push pendente':'Pedir autorização apenas ao activar' ?></small></span></label><button class="blog-notification-save" type="submit">Guardar preferências</button><p class="blog-notification-status" id="blogNotificationStatus" role="status" aria-live="polite"></p></form><?php endif; ?></div></section>
<script>
const reactionBox=document.getElementById('reactionList');
if(reactionBox){reactionBox.addEventListener('click',async(event)=>{const button=event.target.closest('button[data-reaction]');if(!button)return;const status=document.getElementById('reactionStatus');reactionBox.querySelectorAll('button').forEach(b=>b.disabled=true);try{const body=new URLSearchParams({post_id:reactionBox.dataset.postId,reaction:button.dataset.reaction,csrf:reactionBox.dataset.csrf});const response=await fetch('react.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8','X-Requested-With':'XMLHttpRequest'},body,credentials:'same-origin'});const data=await response.json();if(!response.ok||!data.ok)throw new Error(data.message||'Não foi possível guardar a reacção.');reactionBox.querySelectorAll('button').forEach(b=>{const active=data.selected===b.dataset.reaction;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active?'true':'false');b.querySelector('[data-count]').textContent=data.counts[b.dataset.reaction]??0;});status.textContent=data.selected?'Reacção registada.':'Reacção removida.';}catch(error){status.textContent=error.message;}finally{reactionBox.querySelectorAll('button').forEach(b=>b.disabled=false);}});}
document.querySelectorAll('[data-article-share]').forEach(a=>{const u=encodeURIComponent(location.href),t=encodeURIComponent(document.title),k=a.dataset.articleShare;const urls={whatsapp:'https://wa.me/?text='+t+'%20'+u,facebook:'https://www.facebook.com/sharer/sharer.php?u='+u,linkedin:'https://www.linkedin.com/sharing/share-offsite/?url='+u,x:'https://twitter.com/intent/tweet?url='+u+'&text='+t};a.href=urls[k]||'#';a.target='_blank';a.rel='noopener noreferrer';});
const share=document.getElementById('shareArticle');if(share){share.addEventListener('click',async()=>{const status=document.getElementById('shareStatus');try{if(navigator.share){await navigator.share({title:document.title,url:location.href});}else if(navigator.clipboard){await navigator.clipboard.writeText(location.href);status.textContent='Ligação copiada.';}else{status.textContent='Copie o endereço desta página para partilhar.';}}catch(e){if(e.name!=='AbortError')status.textContent='Não foi possível partilhar automaticamente.';}});}
async function handleGoogleCredential(response){const s=document.getElementById('googleStatus');try{const r=await fetch('../auth/google.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({credential:response.credential,csrf:<?= json_encode($googleLoginCsrf) ?>,nonce:<?= json_encode($googleLoginNonce) ?>})});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'Falha no acesso Google');location.reload()}catch(e){if(s)s.textContent=e.message}}
function decodeVapidKey(value){const padded=value+'='.repeat((4-value.length%4)%4);const raw=atob(padded.replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from(raw,char=>char.charCodeAt(0))}
const notificationForm=document.getElementById('blogNotificationForm');
if(notificationForm){notificationForm.addEventListener('submit',async(event)=>{event.preventDefault();const status=document.getElementById('blogNotificationStatus'),button=notificationForm.querySelector('button[type="submit"]'),emailEnabled=document.getElementById('emailNotification').checked,pushEnabled=document.getElementById('pushNotification').checked;button.disabled=true;status.textContent='A guardar as preferências...';try{let subscription=null;if(pushEnabled){if(!window.isSecureContext||!('serviceWorker'in navigator)||!('PushManager'in window)||!('Notification'in window))throw new Error('Este navegador não permite notificações push seguras.');if(notificationForm.dataset.pushAvailable!=='1')throw new Error('As notificações no navegador ainda não estão configuradas.');let permission=Notification.permission;if(permission==='default')permission=await Notification.requestPermission();if(permission!=='granted')throw new Error('Permita notificações no navegador para activar este canal.');const registration=await navigator.serviceWorker.register('service-worker.js');subscription=await registration.pushManager.getSubscription();if(!subscription)subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:decodeVapidKey(notificationForm.dataset.vapidPublicKey)});}if(emailEnabled&&notificationForm.dataset.emailAvailable!=='1')throw new Error('As notificações por e-mail ainda não estão configuradas.');const response=await fetch('notifications.php',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({csrf:notificationForm.dataset.csrf,email_enabled:emailEnabled,push_enabled:pushEnabled,subscription:subscription?subscription.toJSON():null})});const data=await response.json();if(!response.ok||!data.ok)throw new Error(data.message||'Não foi possível guardar as preferências.');status.textContent=emailEnabled||pushEnabled?'Preferências guardadas. Receberá avisos de novos artigos.':'Notificações desactivadas.';}catch(error){status.textContent=error.message||'Não foi possível guardar as preferências.';}finally{button.disabled=false;}});}
</script><?php include __DIR__ . '/../../app/cookie-consent.php'; ?></body></html>
